$('#register-form').addEventListener('submit',async e=>{e.preventDefault();const d=formValue(e.currentTarget);const r=await action(()=>api('/register',{method:'POST',body:d}));if(r){UCPAnalytics.track('account_created',{role:d.role});$('#register-form [name=password]').value='';authTab(false);$('#login-form [name=email]').value=d.email;$('#login-form [name=password]').focus();msg('Votre compte de test est créé. Connectez-vous pour commencer.','success')}});
$('#logout').addEventListener('click',async()=>{const r=await action(()=>api('/logout',{method:'POST'}));if(r){appState.user=null;appState.csrf=null;appState.view=null;currentDraft=null;appState.projectFilters=null;appState.selectedConversation=null;UCPAnalytics.reset();render()}});
