$('#privacy-open').addEventListener('click',()=>showDialog('Vos données dans cette version',el('div',{},el('p',{text:'Cette version privée conserve les comptes, projets et messages dans une base locale. N’utilisez que des données fictives. Aucun traceur PostHog, enregistrement de session ou paiement n’est activé.'}),el('p',{text:'Les photos sont réencodées sans métadonnées GPS. Elles restent privées par défaut. Si vous cochez le partage avant publication, les artisans compatibles peuvent les consulter dans leur fil. Vous pouvez retirer ce partage dans Mes projets ; les copies déjà téléchargées ne peuvent pas être rappelées. Le propriétaire, la modération et le professionnel sélectionné autorisé conservent leurs accès habituels.'}),el('p',{text:'L’export est disponible dans Mon compte. La suppression d’un compte ayant un historique nécessite une intervention opérateur. Les conditions et durées de conservation doivent être validées avant toute ouverture.'}))));
$('#reset-open').addEventListener('click',()=>{const f=el('form',{},el('p',{text:'Dans ce laboratoire, l’opérateur génère un code temporaire avec la commande recovery.py. Aucun email n’est envoyé. Saisissez le code ici.'}),field('Code de récupération','token','text',{minlength:20,maxlength:128}),field('Nouveau mot de passe','password','password',{minlength:12,maxlength:128}),el('button',{type:'submit',class:'primary',text:'Réinitialiser mon mot de passe'}));f.addEventListener('submit',async e=>{e.preventDefault();const r=await action(()=>api('/v4/account/reset',{method:'POST',body:formValue(f)}),'Mot de passe remplacé. Les anciennes sessions ont été révoquées.');if(r)$('#dialog').close()});showDialog('Récupérer votre accès',f)});
